(()=>{'use strict';const places=[{id:'toronto',name:'Toronto',zh:'多伦多',region:'Ontario',coord:[-79.3832,43.6532]},{id:'montreal',name:'Montréal',zh:'蒙特利尔',region:'Québec',coord:[-73.5673,45.5019]},{id:'banff',name:'Banff',zh:'班夫',region:'Alberta',coord:[-115.5708,51.1784]}];const menu=document.querySelector('.menu-toggle');menu.onclick=()=>{const on=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',on);document.querySelector('.links').classList.toggle('open',on)};const svg=d3.select('#travel-map'),node=svg.node(),layer=svg.append('g'),mapLayer=layer.append('g'),pinsLayer=layer.append('g');let w,h,projection,features,active=null,loaded=false;const buttons=document.querySelector('#cities');places.forEach(p=>{const b=document.createElement('button');b.className='city-choice';b.dataset.city=p.id;b.setAttribute('aria-pressed','false');b.innerHTML='<span><strong>'+p.name+'</strong><small>'+p.zh+' · '+p.region+'</small></span><b>↗</b>';b.onclick=()=>select(p.id,true);buttons.append(b)});let zoom=d3.zoom().scaleExtent([1,16]).on('zoom',e=>{layer.attr('transform',e.transform);pinsLayer.selectAll('.pin').attr('transform',p=>{const q=projection(p.coord);return 'translate('+q[0]+','+q[1]+') scale('+(1/e.transform.k)+')'})});svg.call(zoom).on('dblclick.zoom',null);function view(center,k){const q=projection(center);svg.call(zoom.transform,d3.zoomIdentity.translate(w/2-k*q[0],h/2-k*q[1]).scale(k))}function draw(){w=node.clientWidth;h=node.clientHeight;svg.attr('viewBox','0 0 '+w+' '+h);projection=d3.geoMercator().scale(w/(2*Math.PI)).translate([w/2,h*.58]);const path=d3.geoPath(projection);mapLayer.selectAll('*').remove();mapLayer.append('path').datum(d3.geoGraticule10()).attr('class','graticule').attr('d',path);mapLayer.selectAll('.country').data(features).join('path').attr('class',f=>'country'+(f.properties.name==='Canada'?' canada':'')).attr('d',path);pinsLayer.selectAll('*').remove();const pin=pinsLayer.selectAll('g').data(places).join('g').attr('class',p=>'pin'+(p.id===active?' selected':'')).attr('role','button').attr('tabindex',0).attr('aria-label',p=>'View '+p.name+' travel record').on('click',(e,p)=>{e.stopPropagation();select(p.id,false)}).on('keydown',(e,p)=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select(p.id,false)}});pin.append('circle').attr('class','halo').attr('r',11);pin.append('circle').attr('class','core').attr('r',4);pin.append('text').attr('x',p=>p.id==='toronto'?-13:14).attr('y',p=>p.id==='toronto'?22:-12).attr('text-anchor',p=>p.id==='toronto'?'end':'start').text(p=>p.name);view([-99,52],Math.max(2.5,Math.min(4,w/240)));loaded=true}function select(id,focus){const p=places.find(x=>x.id===id);active=id;document.querySelectorAll('.city-choice').forEach(b=>{b.classList.toggle('selected',b.dataset.city===id);b.setAttribute('aria-pressed',String(b.dataset.city===id))});pinsLayer.selectAll('.pin').classed('selected',d=>d.id===id);document.querySelector('#detail').innerHTML='<div class="eyebrow">Canada / '+p.region+'</div><h3>'+p.name+'</h3><p>'+p.zh+' · '+p.region+', Canada</p><div class="photo-slot"><span>旅行照片待添加</span><small>Personal photos &amp; stories, coming next.</small></div>';if(focus&&loaded)view(p.coord,Math.max(4,d3.zoomTransform(node).k))}const ready=f=>()=>{if(loaded)f()};document.querySelector('#world').onclick=ready(()=>view([0,18],1));document.querySelector('#reset').onclick=ready(()=>view([-99,52],Math.max(2.5,Math.min(4,w/240))));document.querySelector('#zoom-in').onclick=ready(()=>svg.call(zoom.scaleBy,1.5));document.querySelector('#zoom-out').onclick=ready(()=>svg.call(zoom.scaleBy,1/1.5));function pan(px){svg.call(zoom.translateBy,px/d3.zoomTransform(node).k,0)}document.querySelector('#left').onclick=ready(()=>pan(140));document.querySelector('#right').onclick=ready(()=>pan(-140));svg.on('keydown.controls',e=>{if(e.target!==node||!loaded)return;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','=','-'].includes(e.key))e.preventDefault();if(e.key==='ArrowLeft')pan(100);if(e.key==='ArrowRight')pan(-100);if(e.key==='ArrowUp')svg.call(zoom.translateBy,0,100/d3.zoomTransform(node).k);if(e.key==='ArrowDown')svg.call(zoom.translateBy,0,-100/d3.zoomTransform(node).k);if(e.key==='+'||e.key==='=')svg.call(zoom.scaleBy,1.5);if(e.key==='-')svg.call(zoom.scaleBy,1/1.5)});fetch('geo/countries.json').then(r=>{if(!r.ok)throw new Error('map');return r.json()}).then(data=>{features=data.features;draw();document.querySelector('#map-state').textContent='';select('toronto',false)}).catch(()=>{document.querySelector('#map-state').textContent='地图暂时无法加载，请刷新。城市列表仍可浏览。'});let resize;new ResizeObserver(()=>{clearTimeout(resize);resize=setTimeout(()=>{if(loaded)draw()},100)}).observe(node);})();
